import "server-only";

// Embedded rather than read from public/images/header-report.png at request time:
// Next.js 16's outputFileTracingIncludes only ever gets applied for webpack builds
// (Turbopack never populates the chunksTrace data it depends on), so a next.config.ts
// include rule for this asset silently did nothing on `next build` and it 404'd
// (ENOENT) in the deployed function. Inlining the bytes sidesteps bundling/tracing
// entirely.
export const HEADER_BANNER_PNG: Buffer = Buffer.from(
  "",
  "base64",
);
